package io.github.bearisbug.synaxis.baker.anvil;

import net.kyori.adventure.nbt.BinaryTagIO;
import net.kyori.adventure.nbt.CompoundBinaryTag;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URISyntaxException;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.function.UnaryOperator;
import java.util.stream.Stream;

/**
 * The vanilla 26.2 save generated by {@code tools/anvil-fixture/gen.sh}, and the one edit the tests
 * need on a copy of it: replace one chunk's compound. The edited chunk is appended at the end of the
 * file and the header pointed at it, the other chunks keep their vanilla bytes.
 */
final class RegionFixtures {
    static final String REGION = "dimensions/minecraft/overworld/region/r.0.0.mca";
    static final String ENTITIES = "dimensions/minecraft/overworld/entities/r.0.0.mca";

    private static final int SECTOR = 4096;

    private RegionFixtures() {
    }

    static Path world() {
        try {
            return Path.of(RegionFixtures.class.getResource("world").toURI());
        } catch (URISyntaxException e) {
            throw new IllegalStateException(e);
        }
    }

    static Path copyWorld(Path target) throws IOException {
        final Path source = world();
        try (Stream<Path> files = Files.walk(source)) {
            files.forEach(file -> {
                try {
                    final Path copy = target.resolve(source.relativize(file).toString());
                    if (Files.isDirectory(file)) Files.createDirectories(copy);
                    else Files.copy(file, copy);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            });
        }
        return target;
    }

    static CompoundBinaryTag readChunk(Path regionFile, int chunkX, int chunkZ) throws IOException {
        final byte[] file = Files.readAllBytes(regionFile);
        final int location = ByteBuffer.wrap(file).getInt(4 * index(chunkX, chunkZ));
        final int offset = (location >>> 8) * SECTOR;
        final int length = ByteBuffer.wrap(file).getInt(offset);
        return BinaryTagIO.unlimitedReader().read(
                new ByteArrayInputStream(file, offset + 5, length - 1), BinaryTagIO.Compression.ZLIB);
    }

    static void rewriteChunk(Path regionFile, int chunkX, int chunkZ, UnaryOperator<CompoundBinaryTag> edit)
            throws IOException {
        final CompoundBinaryTag edited = edit.apply(readChunk(regionFile, chunkX, chunkZ));
        final ByteArrayOutputStream compressed = new ByteArrayOutputStream();
        BinaryTagIO.writer().writeNamed(Map.entry("", edited), compressed, BinaryTagIO.Compression.ZLIB);
        final byte[] data = compressed.toByteArray();

        final byte[] file = Files.readAllBytes(regionFile);
        final int firstSector = (file.length + SECTOR - 1) / SECTOR;
        final int sectors = (5 + data.length + SECTOR - 1) / SECTOR;
        final ByteBuffer out = ByteBuffer.allocate((firstSector + sectors) * SECTOR);
        out.put(file);
        out.putInt(4 * index(chunkX, chunkZ), (firstSector << 8) | sectors);
        out.position(firstSector * SECTOR);
        out.putInt(data.length + 1).put((byte) 2).put(data);
        Files.write(regionFile, out.array());
    }

    private static int index(int chunkX, int chunkZ) {
        return (chunkZ & 31) * 32 + (chunkX & 31);
    }
}
